def possible_meetings(friend):
    name, location, avail_start, avail_end, min_minutes = friend
    total_minutes = int((avail_end - avail_start).total_seconds() // 60)
    intervals = []

    for start_offset in range(total_minutes + 1):
        start = avail_start + timedelta(minutes=start_offset)
        max_duration = total_minutes - start_offset

        if max_duration < min_minutes:
            continue

        for duration in range(min_minutes, max_duration + 1):
            end = start + timedelta(minutes=duration)
            intervals.append((name, location, start, end))

    return intervals

def build_schedule(intervals):
    steps = [f"You start at {START_LOCATION} at {fmt(START_TIME)}."]
    current_location = START_LOCATION
    current_time = START_TIME

    for name, location, start, end in intervals:
        if current_location != location:
            travel_minutes = TRAVEL[(current_location, location)]
            arrival = current_time + timedelta(minutes=travel_minutes)

            if arrival > start:
                return None

            steps.append(
                f"You travel to {location} in {travel_minutes} minutes and arrive at {fmt(arrival)}."
            )
            current_location = location
            current_time = arrival

        if current_time < start:
            steps.append(f"You wait until {fmt(start)}.")
            current_time = start
        elif current_time > start:
            return None

        duration = int((end - start).total_seconds() // 60)
        steps.append(
            f"You meet {name} for {duration} minutes from {fmt(start)} to {fmt(end)}."
        )
        current_time = end

    return steps

